#include <bits/stdc++.h>
using namespace std;

struct Block {
    double x1, z1, x2, z2, y; // y is height
};

int n;
double sx, sz, tx, tz;
vector<Block> blocks;

// Check if ball with radius r can pass
bool canPass(double r) {
    // We'll use a graph of "free spaces": start, end, and each block's edges expanded by r
    // For each pair, check if we can go from one to another without intersecting any block

    // Number of nodes: start(0), end(1), and for each block 4 corners (2,3,4,5 per block)
    int m = 2 + 4 * n;
    vector<vector<double>> dist(m, vector<double>(m, 1e18));

    // Helper to get node index for block i, corner j (0..3)
    auto nodeId = [&](int i, int j) { return 2 + 4*i + j; };

    // Precompute corner positions for each block (expanded by r in xz plane)
    vector<vector<pair<double,double>>> corners(n);
    for (int i = 0; i < n; i++) {
        double x1 = blocks[i].x1, z1 = blocks[i].z1;
        double x2 = blocks[i].x2, z2 = blocks[i].z2;
        // corners: (x1-r, z1-r), (x2+r, z1-r), (x2+r, z2+r), (x1-r, z2+r)
        corners[i] = {
            {x1 - r, z1 - r},
            {x2 + r, z1 - r},
            {x2 + r, z2 + r},
            {x1 - r, z2 + r}
        };
    }

    // Check if a point (x,z) with ball radius r is valid (not inside any block, and on course)
    auto isValidPoint = [&](double x, double z) {
        // Check course boundaries: course is defined by blocks? Actually course is the whole xz plane? 
        // Problem says "ball's bottom point does not leave the course" - course is the area not occupied by blocks?
        // We'll assume entire plane is course except blocks.
        for (int i = 0; i < n; i++) {
            double x1 = blocks[i].x1, z1 = blocks[i].z1;
            double x2 = blocks[i].x2, z2 = blocks[i].z2;
            // Check if point is inside expanded block (including boundary)
            if (x >= x1 - r - 1e-12 && x <= x2 + r + 1e-12 &&
                z >= z1 - r - 1e-12 && z <= z2 + r + 1e-12) {
                // But also need to check height: ball bottom at y=0, block has height y
                // If ball center is at (x, r, z), bottom is at y=0, so as long as r <= block.y it's okay?
                // Actually ball can go over if r <= block.y? No, ball must go around because it's a straight course?
                // Problem says "avoiding rectangular blocks as obstacles" - they are solid.
                // So if ball intersects block in xz, it's invalid regardless of height? 
                // Usually 3D: ball must not intersect block. Ball center at (x, r, z), block from y=0 to y=block.y.
                // Intersection if xz overlap and r < block.y? Actually ball bottom at 0, top at 2r.
                // If r >= block.y, ball can roll over? But problem says "avoiding" so probably must go around.
                // Let's assume blocks are infinite height? Or we consider height: ball can go over if r > block.y?
                // Usually in such problems, blocks have finite height and ball can go over if its radius is larger than block height.
                // But the statement: "ball's bottom point does not leave the course" suggests ball stays on ground.
                // So ball cannot go over blocks. We'll treat blocks as infinite height obstacles.
                return false;
            }
        }
        return true;
    };

    // Check if a straight line segment between two points is valid (no intersection with any block)
    auto canGoStraight = [&](double x1, double z1, double x2, double z2) {
        // Sample many points along segment
        int steps = 100;
        for (int k = 0; k <= steps; k++) {
            double t = (double)k / steps;
            double x = x1 + (x2 - x1) * t;
            double z = z1 + (z2 - z1) * t;
            if (!isValidPoint(x, z)) return false;
        }
        return true;
    };

    // Build graph edges
    vector<pair<double,double>> pts;
    pts.push_back({sx, sz}); // start
    pts.push_back({tx, tz}); // end
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < 4; j++) {
            pts.push_back(corners[i][j]);
        }
    }

    // Check all pairs
    for (int i = 0; i < m; i++) {
        for (int j = i+1; j < m; j++) {
            if (canGoStraight(pts[i].first, pts[i].second, pts[j].first, pts[j].second)) {
                double d = hypot(pts[i].first - pts[j].first, pts[i].second - pts[j].second);
                dist[i][j] = dist[j][i] = d;
            }
        }
    }

    // Dijkstra from start (0) to end (1)
    vector<double> d(m, 1e18);
    vector<bool> vis(m, false);
    d[0] = 0;
    for (int iter = 0; iter < m; iter++) {
        int u = -1;
        double best = 1e18;
        for (int i = 0; i < m; i++) {
            if (!vis[i] && d[i] < best) {
                best = d[i];
                u = i;
            }
        }
        if (u == -1) break;
        vis[u] = true;
        for (int v = 0; v < m; v++) {
            if (dist[u][v] < 1e17 && d[v] > d[u] + dist[u][v]) {
                d[v] = d[u] + dist[u][v];
            }
        }
    }
    return d[1] < 1e17;
}

