#include <bits/stdc++.h>
using namespace std;

struct Rect {
    double x1, y1, x2, y2, h;
};

static const double INF = 1e100;
static const double EPS = 1e-10;

double distPointPoint(double x1, double y1, double x2, double y2) {
    double dx = x1 - x2, dy = y1 - y2;
    return sqrt(dx * dx + dy * dy);
}

double distPointRect(double px, double py, const Rect& r) {
    double dx = 0.0, dy = 0.0;
    if (px < r.x1) dx = r.x1 - px;
    else if (px > r.x2) dx = px - r.x2;
    if (py < r.y1) dy = r.y1 - py;
    else if (py > r.y2) dy = py - r.y2;
    return sqrt(dx * dx + dy * dy);
}

double distRectRect(const Rect& a, const Rect& b) {
    double dx = 0.0, dy = 0.0;
    if (a.x2 < b.x1) dx = b.x1 - a.x2;
    else if (b.x2 < a.x1) dx = a.x1 - b.x2;
    if (a.y2 < b.y1) dy = b.y1 - a.y2;
    else if (b.y2 < a.y1) dy = a.y1 - b.y2;
    return sqrt(dx * dx + dy * dy);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    while (cin >> n) {
        if (n == 0) break;

        double sx, sy, ex, ey;
        cin >> sx >> sy >> ex >> ey;

        vector<Rect> rects(n);
        for (int i = 0; i < n; ++i) {
            double x, y, w, d, h;
            cin >> x >> y >> w >> d >> h;
            rects[i] = {x, y, x + w, y + d, h};
        }

        int S = n, T = n + 1;
        int N = n + 2;

        vector<vector<pair<int,double>>> g(N);

        auto addEdge = [&](int u, int v, double w) {
            g[u].push_back({v, w});
            g[v].push_back({u, w});
        };

        for (int i = 0; i < n; ++i) {
            addEdge(S, i, distPointRect(sx, sy, rects[i]));
            addEdge(T, i, distPointRect(ex, ey, rects[i]));
        }
        addEdge(S, T, distPointPoint(sx, sy, ex, ey));

        for (int i = 0; i < n; ++i) {
            for (int j = i + 1; j < n; ++j) {
                double need = distRectRect(rects[i], rects[j]);
                double lim = fabs(rects[i].h - rects[j].h);
                if (need <= lim + EPS) {
                    addEdge(i, j, 0.0);
                } else {
                    addEdge(i, j, need - lim);
                }
            }
        }

        for (int i = 0; i < n; ++i) {
            double ds = distPointRect(sx, sy, rects[i]);
            if (ds <= rects[i].h + EPS) addEdge(S, i, 0.0);
            else {
                // already added with ds, but true required clearance is ds - h
                // replace by adding corrected edge and keep minimum in Dijkstra naturally
                addEdge(S, i, ds - rects[i].h);
            }

            double dt = distPointRect(ex, ey, rects[i]);
            if (dt <= rects[i].h + EPS) addEdge(T, i, 0.0);
            else addEdge(T, i, dt - rects[i].h);
        }

        // Minimax path: minimize the maximum edge weight along path
        vector<double> best(N, INF);
        priority_queue<pair<double,int>, vector<pair<double,int>>, greater<pair<double,int>>> pq;
        best[S] = 0.0;
        pq.push({0.0, S});

        while (!pq.empty()) {
            auto [cur, u] = pq.top();
            pq.pop();
            if (cur > best[u] + EPS) continue;
            if (u == T) break;
            for (auto [v, w] : g[u]) {
                double nd = max(cur, w);
                if (nd + EPS < best[v]) {
                    best[v] = nd;
                    pq.push({nd, v});
                }
            }
        }

        double ans = best[T] / 2.0;
        if (ans < 0) ans = 0;

        cout << fixed << setprecision(3) << ans << "\n";
    }

    return 0;
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line;
        while ((line = br.readLine()) != null) {
            int n = Integer.parseInt(line.trim());
            if (n == 0) break;

            String[] startEnd = br.readLine().split(" ");
            double sx = Double.parseDouble(startEnd[0]);
            double sy = Double.parseDouble(startEnd[1]);
            double ex = Double.parseDouble(startEnd[2]);
            double ey = Double.parseDouble(startEnd[3]);

            double[][] blocks = new double[n][4];
            for (int i = 0; i < n; i++) {
                String[] parts = br.readLine().split(" ");
                blocks[i][0] = Double.parseDouble(parts[0]); // x1
                blocks[i][1] = Double.parseDouble(parts[1]); // y1
                blocks[i][2] = Double.parseDouble(parts[2]); // x2
                blocks[i][3] = Double.parseDouble(parts[3]); // y2
            }

            double lo = 0, hi = 1e6;
            for (int iter = 0; iter < 100; iter++) {
                double mid = (lo + hi) / 2;
                if (canPass(mid, sx, sy, ex, ey, blocks)) {
                    lo = mid;
                } else {
                    hi = mid;
                }
            }
            System.out.printf("%.2f\n", lo);
        }
    }

    static boolean canPass(double r, double sx, double sy, double ex, double ey, double[][] blocks) {
        int n = blocks.length;
        List<double[]> centers = new ArrayList<>();
        centers.add(new double[]{sx, sy - r});
        centers.add(new double[]{ex, ey - r});

        for (double[] b : blocks) {
            double x1 = b[0], y1 = b[1], x2 = b[2], y2 = b[3];
            if (y2 <= r) continue; // block too low, no collision
            double top = Math.max(y1, y2);
            double bottom = Math.min(y1, y2);
            double left = Math.min(x1, x2);
            double right = Math.max(x1, x2);

            // Add four corner points shifted by radius
            centers.add(new double[]{left - r, top - r});
            centers.add(new double[]{right + r, top - r});
            centers.add(new double[]{left - r, bottom + r});
            centers.add(new double[]{right + r, bottom + r});
        }

        int m = centers.size();
        double[][] dist = new double[m][m];
        for (int i = 0; i < m; i++) {
            Arrays.fill(dist[i], Double.MAX_VALUE);
            dist[i][i] = 0;
        }

        for (int i = 0; i < m; i++) {
            for (int j = i+1; j < m; j++) {
                double dx = centers.get(i)[0] - centers.get(j)[0];
                double dy = centers.get(i)[1] - centers.get(j)[1];
                double d = Math.sqrt(dx*dx + dy*dy);

                // Check if line segment between centers intersects any block
                boolean blocked = false;
                for (double[] b : blocks) {
                    double x1 = b[0], y1 = b[1], x2 = b[2], y2 = b[3];
                    double top = Math.max(y1, y2);
                    double bottom = Math.min(y1, y2);
                    double left = Math.min(x1, x2);
                    double right = Math.max(x1, x2);

                    // Inflate block by radius r
                    if (segmentIntersectsRect(centers.get(i)[0], centers.get(i)[1],
                                              centers.get(j)[0], centers.get(j)[1],
                                              left - r, bottom - r, right + r, top + r)) {
                        blocked = true;
                        break;
                    }
                }
                if (!blocked) {
                    dist[i][j] = dist[j][i] = d;
                }
            }
        }

        // Floyd-Warshall
        for (int k = 0; k < m; k++)
            for (int i = 0; i < m; i++)
                for (int j = 0; j < m; j++)
                    if (dist[i][k] < Double.MAX_VALUE && dist[k][j] < Double.MAX_VALUE)
                        dist[i][j] = Math.min(dist[i][j], dist[i][k] + dist[k][j]);

        return dist[0][1] < Double.MAX_VALUE;
    }

    static boolean segmentIntersectsRect(double x1, double y1, double x2, double y2,
                                         double rx1, double ry1, double rx2, double ry2) {
        // Check if segment intersects rectangle (axis-aligned)
        double minX = Math.min(x1, x2), maxX = Math.max(x1, x2);
        double minY = Math.min(y1, y2), maxY = Math.max(y1, y2);

        if (maxX < rx1 || minX > rx2 || maxY < ry1 || minY > ry2) return false;

        // Check if either endpoint is inside
        if (x1 >= rx1 && x1 <= rx2 && y1 >= ry1 && y1 <= ry2) return true;
        if (x2 >= rx1 && x2 <= rx2 && y2 >= ry1 && y2 <= ry2) return true;

        // Check edges
        return lineIntersectsLine(x1, y1, x2, y2, rx1, ry1, rx2, ry1) ||
               lineIntersectsLine(x1, y1, x2, y2, rx2, ry1, rx2, ry2) ||
               lineIntersectsLine(x1, y1, x2, y2, rx1, ry1, rx1, ry2) ||
               lineIntersectsLine(x1, y1, x2, y2, rx2, ry2, rx1, ry2);
    }

    static boolean lineIntersectsLine(double x1, double y1, double x2, double y2,
                                      double x3, double y3, double x4, double y4) {
        double d1 = cross(x3, y3, x4, y4, x1, y1);
        double d2 = cross(x3, y3, x4, y4, x2, y2);
        double d3 = cross(x1, y1, x2, y2, x3, y3);
        double d4 = cross(x1, y1, x2, y2, x4, y4);
        if (((d1 > 0 && d2 < 0) || (d1 < 0 && d2 > 0)) &&
            ((d3 > 0 && d4 < 0) || (d3 < 0 && d4 > 0))) return true;
        if (d1 == 0 && onSegment(x3, y3, x4, y4, x1, y1)) return true;
        if (d2 == 0 && onSegment(x3, y3, x4, y4, x2, y2)) return true;
        if (d3 == 0 && onSegment(x1, y1, x2, y2, x3, y3)) return true;
        if (d4 == 0 && onSegment(x1, y1, x2, y2, x4, y4)) return true;
        return false;
    }

    static double cross(double x1, double y1, double x2, double y2, double x, double y) {
        return (x2 - x1) * (y - y1) - (y2 - y1) * (x - x1);
    }

    static boolean onSegment(double x1, double y1, double x2, double y2, double x, double y) {
        return Math.min(x1, x2) <= x && x <= Math.max(x1, x2) &&
               Math.min(y1, y2) <= y && y <= Math.max(y1, y2);
    }
}

