import java.io.*;
import java.util.*;

/*
 * Roll-A-Big-Ball
 *
 * We need the maximum radius r of a ball that can move from start to end
 * on the plane z=0 while avoiding axis-aligned rectangular blocks of height h.
 *
 * A ball of radius r collides with a block iff its center comes within
 * horizontal distance sqrt(2rh - h^2) from the rectangle, provided h <= 2r.
 * If h > 2r, then any horizontal overlap is forbidden, i.e. effective expansion
 * is at least 0 and in fact the center cannot be above the rectangle footprint.
 *
 * More directly, for a fixed r:
 *   - if h >= 2r, expanded radius = 0
 *   - else expanded radius = sqrt(2*r*h - h*h)
 *
 * The ball's center must also stay within the course strip determined by the
 * segment from start to end, because the bottom point may not leave the course.
 * That means the center path must stay within distance r from the segment and
 * also not go beyond the endpoints. This is equivalent to moving inside the
 * capsule (segment Minkowski-summed with disk radius r).
 *
 * We determine feasibility for a fixed r by checking whether the two endpoints
 * of the center path (which are exactly the given start/end lifted by radius r)
 * are connected inside the capsule after removing all expanded obstacles.
 *
 * Since all geometry is continuous and obstacles are rectangles expanded by a
 * radius, we can solve via planar separation: start and end are disconnected iff
 * obstacles together with the outside of the capsule form a barrier. We model
 * obstacles as nodes and connect intersecting/touching expanded obstacles.
 * Also connect an obstacle to one of four capsule boundary "sides" if it touches:
 *   LEFT cap, RIGHT cap, UPPER side, LOWER side
 * in local coordinates along the segment.
 *
 * Then forbidden barrier exists if any of these pairs become connected:
 *   UPPER-LOWER, LEFT-UPPER, LEFT-LOWER, RIGHT-UPPER, RIGHT-LOWER, LEFT-RIGHT
 * Actually any connection separating start from end inside the capsule.
 *
 * A simpler robust method for this problem size: build arrangement graph of all
 * obstacle corners/intersections plus start/end and run visibility in free space
 * is too large/fragile.
 *
 * Instead, because the free region is a capsule (simply connected) and obstacles
 * are connected closed sets, start and end are disconnected iff some connected
 * component of forbidden region touches both "opposite" boundary chains of the
 * capsule. In capsule topology, the relevant opposite pairs are:
 *   UPPER with LOWER
 *   LEFT with UPPER
 *   LEFT with LOWER
 *   RIGHT with UPPER
 *   RIGHT with LOWER
 *   LEFT with RIGHT
 * This conservative set is standard for rectangle/corridor separation and works.
 *
 * We binary search r.
 */

public class Main {
    static final double EPS = 1e-9;

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        double nextDouble() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            double val = 0;
            while (c > ' ' && c != '.' && c != -1) {
                val = val * 10 + (c - '0');
                c = read();
            }
            if (c == '.') {
                double mul = 0.1;
                c = read();
                while (c > ' ' && c != -1) {
                    val += (c - '0') * mul;
                    mul *= 0.1;
                    c = read();
                }
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int)Math.round(nextDouble());
        }
    }

    static class Rect {
        double x1, y1, x2, y2, h;
    }

    static int n;
    static double sx, sy, ex, ey;
    static Rect[] rects;

    static double dx, dy, L;

    static class DSU {
        int[] p, r;
        DSU(int n) {
            p = new int[n];
            r = new int[n];
            for (int i = 0; i < n; i++) p[i] = i;
        }
        int find(int x) {
            while (p[x] != x) {
                p[x] = p[p[x]];
                x = p[x];
            }
            return x;
        }
        void union(int a, int b) {
            a = find(a); b = find(b);
            if (a == b) return;
            if (r[a] < r[b]) p[a] = b;
            else if (r[a] > r[b]) p[b] = a;
            else { p[b] = a; r[a]++; }
        }
        boolean same(int a, int b) { return find(a) == find(b); }
    }

    // transform world point to local coordinates:
    // u along segment from start to end, v perpendicular (left positive)
    static double[] toLocal(double x, double y) {
        double px = x - sx, py = y - sy;
        double u = (px * dx + py * dy) / L;
        double v = (-px * dy + py * dx) / L;
        return new double[]{u, v};
    }

    static double expandedRadius(double r, double h) {
        if (h >= 2.0 * r) return 0.0;
        double val = 2.0 * r * h - h * h;
        if (val < 0) val = 0;
        return Math.sqrt(val);
    }

    static boolean intersectsExpanded(Rect a, double ea, Rect b, double eb) {
        return a.x1 - ea <= b.x2 + eb + EPS &&
               b.x1 - eb <= a.x2 + ea + EPS &&
               a.y1 - ea <= b.y2 + eb + EPS &&
               b.y1 - eb <= a.y2 + ea + EPS;
    }

    static boolean feasible(double r) {
        // If start/end themselves are inside forbidden region, impossible.
        for (Rect rec : rects) {
            double e = expandedRadius(r, rec.h);
            if (pointRectDist(sx, sy, rec) <= e + EPS) return false;
            if (pointRectDist(ex, ey, rec) <= e + EPS) return false;
        }

        int LEFT = n, RIGHT = n + 1, UPPER = n + 2, LOWER = n + 3;
