        for (int v = 0; v < m; v++) {
            if (visited[v]) continue;
            // Check if segment from pts[u] to pts[v] does not intersect any expanded block
            if (!segment_intersects(pts[u], pts[v], r)) {
                visited[v] = 1;
                queue[back++] = v;
            }
        }
    }
    free(pts); free(visited); free(queue);
    return 0;
}

