#include <stdio.h>
#include <stdlib.h>
#include <math.h>

typedef struct {
    double x1, y1, x2, y2, h;
} Rect;

typedef struct {
    int to;
    double w;
    int next;
} Edge;

static double sqr(double x) { return x * x; }

static double point_rect_dist(double x, double y, const Rect *r) {
    double dx = 0.0, dy = 0.0;
    if (x < r->x1) dx = r->x1 - x;
    else if (x > r->x2) dx = x - r->x2;
    if (y < r->y1) dy = r->y1 - y;
    else if (y > r->y2) dy = y - r->y2;
    return sqrt(dx * dx + dy * dy);
}

static double rect_rect_dist(const Rect *a, const Rect *b) {
    double dx = 0.0, dy = 0.0;
    if (a->x2 < b->x1) dx = b->x1 - a->x2;
    else if (b->x2 < a->x1) dx = a->x1 - b->x2;
    if (a->y2 < b->y1) dy = b->y1 - a->y2;
    else if (b->y2 < a->y1) dy = a->y1 - b->y2;
    return sqrt(dx * dx + dy * dy);
}

/*
   Interpretation used:
   - Ball center moves in the plane.
   - A block of height h is impassable for radius r iff h > r.
   - Then the center must stay at distance at least r from that rectangle.
   - Start/end are points for the ball's bottom point, so center is vertically above them;
     in the 2D top view they are just points that must be connected.
   - Largest feasible radius is the minimax path value in a graph:
       nodes = start, end, all blocks
       edge weight = clearance distance between geometric objects
     considering only blocks with h > r.
   Equivalent solution:
     Build complete graph with weights:
       start/end to block = point-rect distance
       block-block = rect-rect distance
       start-end = distance between points
     The answer is the minimum bottleneck value between start and end,
     where every block node has threshold h as well.
   We solve by Dijkstra-like widest/minimax path over all nodes, where entering
   a block node i is limited by h_i too.
*/

int main(void) {
    int n;
    while (scanf("%d", &n) == 1) {
        double sx, sy, tx, ty;
        if (scanf("%lf %lf %lf %lf", &sx, &sy, &tx, &ty) != 4) return 0;

        Rect *r = NULL;
        if (n > 0) {
            r = (Rect *)malloc(sizeof(Rect) * n);
            for (int i = 0; i < n; ++i) {
                scanf("%lf %lf %lf %lf %lf", &r[i].x1, &r[i].y1, &r[i].x2, &r[i].y2, &r[i].h);
                if (r[i].x1 > r[i].x2) {
                    double t = r[i].x1; r[i].x1 = r[i].x2; r[i].x2 = t;
                }
                if (r[i].y1 > r[i].y2) {
                    double t = r[i].y1; r[i].y1 = r[i].y2; r[i].y2 = t;
                }
            }
        }

        int V = n + 2;          /* 0=start, 1=end, 2..n+1 blocks */
        int E = V * (V - 1);
        Edge *edges = (Edge *)malloc(sizeof(Edge) * E);
        int *head = (int *)malloc(sizeof(int) * V);
        for (int i = 0; i < V; ++i) head[i] = -1;
        int ec = 0;

        #define ADD(u,v,wv) do { \
            edges[ec].to = (v); edges[ec].w = (wv); edges[ec].next = head[(u)]; head[(u)] = ec++; \
        } while (0)

        double dse = hypot(sx - tx, sy - ty);
        ADD(0, 1, dse);
        ADD(1, 0, dse);

        for (int i = 0; i < n; ++i) {
            double ds = point_rect_dist(sx, sy, &r[i]);
            double dt = point_rect_dist(tx, ty, &r[i]);
            int id = i + 2;
            ADD(0, id, ds); ADD(id, 0, ds);
            ADD(1, id, dt); ADD(id, 1, dt);
        }

        for (int i = 0; i < n; ++i) {
            for (int j = i + 1; j < n; ++j) {
                double d = rect_rect_dist(&r[i], &r[j]);
                int a = i + 2, b = j + 2;
                ADD(a, b, d);
                ADD(b, a, d);
            }
        }

        /* minimax shortest path: dist[v] = minimum possible maximum edge weight on path from start */
        double *dist = (double *)malloc(sizeof(double) * V);
        int *used = (int *)calloc(V, sizeof(int));
        for (int i = 0; i < V; ++i) dist[i] = 1e100;
        dist[0] = 0.0;

        for (int it = 0; it < V; ++it) {
            int u = -1;
            double best = 1e100;
            for (int i = 0; i < V; ++i) {
                if (!used[i] && dist[i] < best) {
                    best = dist[i];
                    u = i;
                }
            }
            if (u == -1) break;
            used[u] = 1;
            for (int e = head[u]; e != -1; e = edges[e].next) {
                int v = edges[e].to;
                double nd = dist[u] > edges[e].w ? dist[u] : edges[e].w;
                if (nd < dist[v]) dist[v] = nd;
            }
        }

        /*
          Also constrained by heights of crossed block-nodes:
          the true maximal radius is min over any separating chain of obstacles,
          equivalently the minimax value among distances and heights.
          Incorporate heights by taking answer as min bottleneck path in augmented metric,
          where each block node i has self-threshold h_i. That is equivalent to capping
          dist at h_i when visiting node i.
          Easier exact way: run Dijkstra on node costs already computed by
          redefining node distance as min over paths of max(edge weights, node heights on path).
        */
        for (int i = 0; i < V; ++i) {
            dist[i] = 1e100;
            used[i] = 0;
        }
        dist[0] = 0.0;

        for (int it = 0; it < V; ++it) {
            int u = -1;
            double best = 1e100;
            for (int i = 0; i < V; ++i) {
                if (!used[i] && dist[i] < best) {
                    best = dist[i];
                    u = i;
                }
            }
            if (u == -1) break;
            used[u] = 1;
            for (int e = head[u]; e != -1; e = edges[e].next) {
                int v = edges[e].to;
                double nd = dist[u];
                if (edges[e].w > nd) nd = edges[e].w;
                if (v >= 2 && r[v - 2].h > nd) nd = r[v - 2].h;
                if (nd < dist[v]) dist[v] = nd;
            }
        }

        printf("%.6f\n", dist[1]);

        free(r);
        free(edges);
        free(head);
        free(dist);
        free(used);
    }
    return 0;
}
